"""Tupras Stadyumu (Besiktas) - procedural low-poly model for the three.js site.

Run headless:

    blender -b --python stadyum/blender/build_tupras.py -- [options]

Options (after the "--"):
    --stage N          build only the first N stages (1 body, 2 roof, 3 facade + south building, 4 details)  [4]
    --out FILE         GLB output path               [stadyum/public/models/tupras.glb]
    --tex DIR          texture directory             [stadyum/blender/build/tex]  (generated by make_textures.py)
    --no-export        do not write the GLB
    --previews LIST    comma list of preview views to render (top,east,south,inside,under,...) [none]
    --preview-dir DIR  where the previews go         [stadyum/.qa/blender]
    --samples N        Cycles samples for previews   [24]
    --save-blend FILE  also save a .blend

Everything is authored in the website's three.js world (x = pitch width, z = pitch
length, y up, north = -z) and converted to Blender's Z-up while the meshes are
created; the glTF exporter (export_yup) then gives back exactly the same axes.
"""
import argparse
import math
import os
import subprocess
import sys
import time

import bpy
import numpy as np
from mathutils import Vector

HERE = os.path.dirname(os.path.realpath(__file__))
sys.path.insert(0, HERE)
import ringlib as RL  # noqa: E402

ROOT = os.path.abspath(os.path.join(HERE, '..'))


def parse_args():
    argv = sys.argv[sys.argv.index('--') + 1:] if '--' in sys.argv else []
    ap = argparse.ArgumentParser()
    ap.add_argument('--stage', type=int, default=4)
    ap.add_argument('--out', default=os.path.join(ROOT, 'public', 'models', 'tupras.glb'))
    ap.add_argument('--tex', default=os.path.join(HERE, 'build', 'tex'))
    ap.add_argument('--no-export', action='store_true')
    ap.add_argument('--previews', default='')
    ap.add_argument('--preview-dir', default=os.path.join(ROOT, '.qa', 'blender'))
    ap.add_argument('--preview-prefix', default='')
    ap.add_argument('--samples', type=int, default=24)
    ap.add_argument('--save-blend', default='')
    return ap.parse_args(argv)


# =============================================================================
# materials
# =============================================================================
def srgb(h):
    """'#rrggbb' -> linear rgba."""
    h = h.lstrip('#')
    c = [int(h[i:i + 2], 16) / 255.0 for i in (0, 2, 4)]
    lin = [(v / 12.92) if v <= 0.04045 else ((v + 0.055) / 1.055) ** 2.4 for v in c]
    return (*lin, 1.0)


MAT_SPECS = {
    # name: (srgb colour, roughness, metallic, texture file, clamp)
    'roof_fabric': ('#ffffff', 0.80, 0.0, 'roof_top.jpg', True),
    'roof_under': ('#a9afb8', 0.65, 0.15, None, False),
    'steel_dark': ('#2a2d33', 0.45, 0.75, None, False),
    'facade_stone': ('#cec6b2', 0.70, 0.0, None, False),
    'facade_glass': ('#ffffff', 0.10, 0.0, 'glass.jpg', False),
    'concrete': ('#8c8f96', 0.90, 0.0, None, False),
    'seats': ('#ffffff', 0.85, 0.0, 'seats.jpg', False),
    'pitch': ('#ffffff', 0.95, 0.0, 'pitch.jpg', True),
    'grass': ('#245a2c', 1.00, 0.0, None, False),
    'podium_dark': ('#2b2d31', 0.85, 0.0, None, False),
    'brick_red': ('#74301f', 0.75, 0.0, None, False),
}
_MATS = {}


def get_mat(name, tex_dir):
    if name in _MATS:
        return _MATS[name]
    col, rough, metal, texf, clamp = MAT_SPECS[name]
    m = bpy.data.materials.new(name)
    m.use_nodes = True
    nt = m.node_tree
    bsdf = nt.nodes['Principled BSDF']
    bsdf.inputs['Base Color'].default_value = srgb(col)
    bsdf.inputs['Roughness'].default_value = rough
    bsdf.inputs['Metallic'].default_value = metal
    if texf:
        path = os.path.join(tex_dir, texf)
        img = bpy.data.images.load(path)
        img.name = os.path.splitext(texf)[0]
        img.colorspace_settings.name = 'sRGB'
        tx = nt.nodes.new('ShaderNodeTexImage')
        tx.image = img
        tx.interpolation = 'Linear'
        tx.extension = 'EXTEND' if clamp else 'REPEAT'
        nt.links.new(tx.outputs['Color'], bsdf.inputs['Base Color'])
    m.use_backface_culling = True
    _MATS[name] = m
    return m


# =============================================================================
# mesh accumulation (authoring in three.js coordinates, converted at build time)
# =============================================================================
def to_bl(V):
    V = np.asarray(V, np.float64)
    return np.stack([V[..., 0], -V[..., 2], V[..., 1]], axis=-1)


class Part:
    """One exported object: any number of material slots, quads + tris."""

    def __init__(self, name, mats):
        self.name, self.mats = name, list(mats)
        self.V, self.Q, self.QU, self.QM = [], [], [], []
        self.T, self.TU, self.TM = [], [], []
        self.nv = 0

    def _mat(self, m):
        return self.mats.index(m) if isinstance(m, str) else int(m)

    def add_quads(self, V, Q, UV, mat):
        V = np.asarray(V, float).reshape(-1, 3)
        Q = np.asarray(Q, int).reshape(-1, 4)
        UV = np.asarray(UV, float).reshape(-1, 4, 2)
        self.V.append(V)
        self.Q.append(Q + self.nv)
        self.QU.append(UV)
        self.QM.append(np.full(len(Q), self._mat(mat)))
        self.nv += len(V)

    def add_tris(self, V, T, UV, mat):
        V = np.asarray(V, float).reshape(-1, 3)
        T = np.asarray(T, int).reshape(-1, 3)
        UV = np.asarray(UV, float).reshape(-1, 3, 2)
        self.V.append(V)
        self.T.append(T + self.nv)
        self.TU.append(UV)
        self.TM.append(np.full(len(T), self._mat(mat)))
        self.nv += len(V)

    def add_prims(self, V, Q, QUV, T, TUV, mat):
        """quads and tris sharing one vertex array (no duplicated vertices)."""
        V = np.asarray(V, float).reshape(-1, 3)
        m = self._mat(mat)
        self.V.append(V)
        if len(Q):
            self.Q.append(np.asarray(Q, int).reshape(-1, 4) + self.nv)
            self.QU.append(np.asarray(QUV, float).reshape(-1, 4, 2))
            self.QM.append(np.full(len(Q), m))
        if len(T):
            self.T.append(np.asarray(T, int).reshape(-1, 3) + self.nv)
            self.TU.append(np.asarray(TUV, float).reshape(-1, 3, 2))
            self.TM.append(np.full(len(T), m))
        self.nv += len(V)

    @property
    def tri_count(self):
        return 2 * sum(len(q) for q in self.Q) + sum(len(t) for t in self.T)

    def build(self, tex_dir, smooth_deg=35.0):
        V = to_bl(np.concatenate(self.V))
        Q = np.concatenate(self.Q) if self.Q else np.zeros((0, 4), int)
        T = np.concatenate(self.T) if self.T else np.zeros((0, 3), int)
        faces = [tuple(f) for f in Q.tolist()] + [tuple(f) for f in T.tolist()]
        mesh = bpy.data.meshes.new(self.name)
        mesh.from_pydata(V.tolist(), [], faces)
        uvs = []
        if len(Q):
            uvs.append(np.concatenate(self.QU).reshape(-1, 2))
        if len(T):
            uvs.append(np.concatenate(self.TU).reshape(-1, 2))
        uvl = mesh.uv_layers.new(name='UVMap')
        uvl.data.foreach_set('uv', np.concatenate(uvs).astype(np.float32).ravel())
        mi = np.concatenate(([np.concatenate(self.QM)] if self.Q else []) + ([np.concatenate(self.TM)] if self.T else []))
        mesh.polygons.foreach_set('material_index', mi.astype(np.int32))
        mesh.update()
        mesh.validate(verbose=False)
        for mn in self.mats:
            mesh.materials.append(get_mat(mn, tex_dir))
        obj = bpy.data.objects.new(self.name, mesh)
        bpy.context.scene.collection.objects.link(obj)
        bpy.ops.object.select_all(action='DESELECT')
        obj.select_set(True)
        bpy.context.view_layer.objects.active = obj
        bpy.ops.object.shade_smooth_by_angle(angle=math.radians(smooth_deg))
        obj.select_set(False)
        return obj


# ---- geometry primitives ----------------------------------------------------
def _quad_normals(P4):
    a = P4[:, 2] - P4[:, 0]
    b = P4[:, 3] - P4[:, 1]
    return np.cross(a, b)


def grid_surface(part, P, UV, mat, exp, nxz=None, closed=True):
    """Quad surface over a (nt, nd) vertex grid (wrapping in t when closed).

    UV has shape (nt + closed, nd, 2). exp = expected facing of the surface
    ('u','d' up/down; 'o','i' radial outward/inward) - the whole grid is flipped
    when its mean normal disagrees, so the winding is always right.
    """
    nt, nd, _ = P.shape
    nq = nt if closed else nt - 1
    I, J = np.meshgrid(np.arange(nq), np.arange(nd - 1), indexing='ij')
    In = (I + 1) % nt
    idx = lambda i, j: i * nd + j  # noqa: E731
    Q = np.stack([idx(I, J), idx(In, J), idx(In, J + 1), idx(I, J + 1)], -1).reshape(-1, 4)
    UVq = np.stack([UV[I, J], UV[I + 1, J], UV[I + 1, J + 1], UV[I, J + 1]], -2).reshape(-1, 4, 2)
    Pf = P.reshape(-1, 3)
    N = _quad_normals(Pf[Q])
    if exp in ('u', 'd'):
        s = N[:, 1].sum()
        want = 1 if exp == 'u' else -1
    else:
        nn = np.repeat(nxz[:nq], nd - 1, axis=0)           # (nq*(nd-1), 2)
        s = (N[:, 0] * nn[:, 0] + N[:, 2] * nn[:, 1]).sum()
        want = 1 if exp == 'o' else -1
    if s * want < 0:
        Q = Q[:, ::-1]
        UVq = UVq[:, ::-1]
    part.add_quads(Pf, Q, UVq, mat)


def arc_u(x, z, closed=True):
    """cumulative length along a closed polyline sampled at (x, z): returns nt+1 values."""
    xe = np.append(x, x[0]) if closed else x
    ze = np.append(z, z[0]) if closed else z
    return np.concatenate([[0.0], np.cumsum(np.hypot(np.diff(xe), np.diff(ze)))])


def loft(part, ring, ts, profile, exp, mats, uscale=4.0, vscale=4.0, uvfn=None, u_override=None, v0=0.0, closed=True):
    """Extrude profile [(d, y), ...] along the ring samples ts. Each profile segment gets its
    own vertex rows (hard edges). closed=True wraps around the ring; closed=False is an open strip."""
    ts = np.asarray(ts, float)
    n = len(ts)
    nu = n + 1 if closed else n
    if isinstance(mats, (str, int)):
        mats = [mats] * (len(profile) - 1)
    vacc = v0
    for k in range(len(profile) - 1):
        (d0, y0), (d1, y1) = profile[k], profile[k + 1]
        x0, z0, nx, nz = ring.point(ts, d0)
        x1, z1, _, _ = ring.point(ts, d1)
        P = np.stack([np.stack([x0, np.full(n, y0), z0], -1), np.stack([x1, np.full(n, y1), z1], -1)], axis=1)
        vl = math.hypot(d1 - d0, y1 - y0)
        if uvfn is not None:
            UVp = uvfn(np.concatenate([P, P[:1]], 0) if closed else P)
        else:
            u0 = arc_u(x0, z0, closed) / uscale if u_override is None else u_override(ts, d0)
            u1 = arc_u(x1, z1, closed) / uscale if u_override is None else u_override(ts, d1)
            UVp = np.stack([np.stack([u0, np.full(nu, vacc / vscale)], -1),
                            np.stack([u1, np.full(nu, (vacc + vl) / vscale)], -1)], axis=1)
        vacc += vl
        grid_surface(part, P, UVp, mats[k], exp[k], np.stack([nx, nz], -1), closed=closed)


def ts_range(ring, t0, t1, arc_seg=24):
    """parameter samples covering [t0, t1] (open strip), t may exceed the period."""
    base = ring.samples(arc_seg)
    allt = np.concatenate([base + ring.P * k for k in (-1, 0, 1, 2)])
    inside = allt[(allt > t0 + 1e-6) & (allt < t1 - 1e-6)]
    return np.unique(np.round(np.concatenate([[t0], inside, [t1]]), 6))


def poly_fan(part, pts3, centre3, outward, mat, uv=(0.5, 0.5)):
    """Convex polygon given as an ordered list of 3D points -> triangle fan around centre3,
    oriented so the normal points along `outward` (3-vector)."""
    pts3 = np.asarray(pts3, float)
    k = len(pts3)
    V = np.concatenate([[centre3], pts3])
    tris = np.array([[0, 1 + i, 1 + (i + 1) % k] for i in range(k)])
    nrm = np.cross(V[tris][:, 1] - V[tris][:, 0], V[tris][:, 2] - V[tris][:, 0]).sum(0)
    if np.dot(nrm, outward) < 0:
        tris = tris[:, ::-1]
    part.add_tris(V, tris, np.tile(np.array(uv), (len(tris), 3, 1)), mat)


def box_prism(part, centers, axes_u, axes_v, hu, hv, y0, y1, mat, caps=(True, True), chamfer=0.0, uv=(0.5, 0.5)):
    """Vertical prisms with an (optionally chamfered) rectangular footprint.

    centers (N,2) xz; axes_u/axes_v (N,2) unit vectors in xz; hu, hv half sizes. The shaft is
    y0..y1 (scalars or (N,)). Orientation fixed so all faces point outwards.
    """
    N = len(centers)
    c = chamfer
    poly = [(-hu + c, -hv), (hu - c, -hv), (hu, -hv + c), (hu, hv - c), (hu - c, hv), (-hu + c, hv), (-hu, hv - c), (-hu, -hv + c)]
    if c <= 0:
        poly = [(-hu, -hv), (hu, -hv), (hu, hv), (-hu, hv)]
    poly = np.array(poly)
    k = len(poly)
    y0 = np.broadcast_to(np.asarray(y0, float), (N,))
    y1 = np.broadcast_to(np.asarray(y1, float), (N,))
    xz = (centers[:, None, :] + poly[None, :, 0:1] * axes_u[:, None, :] + poly[None, :, 1:2] * axes_v[:, None, :])  # (N,k,2)
    bot = np.concatenate([xz[..., 0:1], np.broadcast_to(y0[:, None, None], (N, k, 1)), xz[..., 1:2]], -1)
    top = np.concatenate([xz[..., 0:1], np.broadcast_to(y1[:, None, None], (N, k, 1)), xz[..., 1:2]], -1)
    V = np.concatenate([bot, top], 1).reshape(-1, 3)            # per prism: k bottom + k top
    base = (np.arange(N) * 2 * k)[:, None]
    quads = []
    for i in range(k):
        j = (i + 1) % k
        quads.append(np.stack([base[:, 0] + i, base[:, 0] + j, base[:, 0] + k + j, base[:, 0] + k + i], -1))
    quads = np.stack(quads, 1).reshape(-1, 4)
    # orient: outward (away from prism centre)
    cen = np.repeat(np.concatenate([centers[:, 0:1], ((y0 + y1) / 2)[:, None], centers[:, 1:2]], -1), k, axis=0)
    fc = V[quads].mean(1)
    nrm = _quad_normals(V[quads])
    flip = ((nrm * (fc - cen)).sum(1) < 0)
    quads[flip] = quads[flip][:, ::-1]
    all_tris = []
    for which, on in ((1, caps[1]), (0, caps[0])):
        if not on:
            continue
        off = k if which else 0
        tris = []
        for i in range(1, k - 1):
            tris.append(np.stack([base[:, 0] + off, base[:, 0] + off + i, base[:, 0] + off + i + 1], -1))
        tris = np.stack(tris, 1).reshape(-1, 3)
        fcen = np.repeat(np.concatenate([centers[:, 0:1], ((y0 + y1) / 2)[:, None], centers[:, 1:2]], -1), k - 2, axis=0)
        n3 = np.cross(V[tris][:, 1] - V[tris][:, 0], V[tris][:, 2] - V[tris][:, 0])
        fcc = V[tris].mean(1)
        fl = ((n3 * (fcc - fcen)).sum(1) < 0)
        tris[fl] = tris[fl][:, ::-1]
        all_tris.append(tris)
    T = np.concatenate(all_tris) if all_tris else np.zeros((0, 3), int)
    part.add_prims(V, quads, np.tile(np.array(uv), (len(quads), 4, 1)), T, np.tile(np.array(uv), (len(T), 3, 1)), mat)


# =============================================================================
# scene helpers
# =============================================================================
def reset_scene():
    bpy.ops.wm.read_factory_settings(use_empty=True)
    sc = bpy.context.scene
    sc.unit_settings.system = 'METRIC'
    sc.unit_settings.scale_length = 1.0


OBJECTS = {}


def finish(part, tex_dir):
    obj = part.build(tex_dir)
    OBJECTS[part.name] = obj
    print('  %-16s %7d tris  %2d mats' % (part.name, part.tri_count, len(part.mats)))
    return obj


# =============================================================================
# STAGE 1 - main body: pitch, stand bowl shell, concourse, podium
# =============================================================================
SINK = 0.30            # the shell sits this far below the procedural stair treads (no z-fighting)
SEAT_ROW_U = 2.2       # metres of seats per texture tile (4 seats)


def aisles(part, ring0, tier, n_aisle, slope_y, mat, extra=0.0):
    """thin light strips running down the seat deck (radial aisles)."""
    tt = (np.arange(n_aisle) + 0.5) * ring0.P / n_aisle
    d0, d1 = tier['d0'], tier['d1'] + extra
    V = []
    for t in tt:
        xs, zs, nx, nz = (a_[0] for a_ in ring0.point(np.array([t]), d0))
        xe, ze, _, _ = (a_[0] for a_ in ring0.point(np.array([t]), d1))
        tx, tz = -nz, nx
        w = 0.55
        y0, y1 = slope_y(tier, d0) + 0.04, slope_y(tier, d1) + 0.04
        V.append([[xs - tx * w, y0, zs - tz * w], [xs + tx * w, y0, zs + tz * w], [xe + tx * w, y1, ze + tz * w], [xe - tx * w, y1, ze - tz * w]])
    V = np.array(V)
    Q = np.arange(len(V) * 4).reshape(-1, 4)
    N = _quad_normals(V.reshape(-1, 3)[Q])
    Q[N[:, 1] < 0] = Q[N[:, 1] < 0][:, ::-1]
    part.add_quads(V.reshape(-1, 3), Q, np.zeros((len(Q), 4, 2)) + 0.5, mat)


def stage1(tex_dir, details=False):
    ring0 = RL.Ring(0.0)
    ts = ring0.samples(arc_seg=16)

    # ---- pitch (striped plane) + apron --------------------------------------
    p = Part('pitch', ['pitch', 'grass'])
    w, l, y = RL.PITCH_W / 2, RL.PITCH_L / 2, RL.PITCH_Y
    P = np.array([[-w, y, -l], [w, y, -l], [w, y, l], [-w, y, l]])
    uv = np.array([[0, 1], [1, 1], [1, 0], [0, 0]], float)
    p.add_quads(P, [[0, 3, 2, 1]], uv[[0, 3, 2, 1]], 'pitch')          # normal +y
    # apron: rounded rectangle out to the front wall of the stands, slightly below the pitch
    x, z, _, _ = ring0.point(ts, 4.9)
    n = len(ts)
    V = np.concatenate([[[0.0, 0.30, 0.0]], np.stack([x, np.full(n, 0.30), z], -1)])
    tris = np.array([[0, 1 + (i + 1) % n, 1 + i] for i in range(n)])
    # clockwise ring -> (0, i+1, i) points up? orient by normal
    nrm = np.cross(V[tris][:, 1] - V[tris][:, 0], V[tris][:, 2] - V[tris][:, 0])
    if nrm[:, 1].sum() < 0:
        tris = tris[:, ::-1]
    p.add_tris(V, tris, np.zeros((len(tris), 3, 2)) + 0.5, 'grass')
    finish(p, tex_dir)

    # ---- stand shells ---------------------------------------------------------
    lo, mid, up = RL.TIER_LOW, RL.TIER_MID, RL.TIER_UP

    def slope_y(t, d):
        return t['y0'] - SINK + (d - t['d0']) * (t['y1'] - t['y0']) / (t['d1'] - t['d0'])

    rows_lo = max(1, round((lo['y1'] - lo['y0']) / RL.ROW_RISE))
    rows_up = max(1, round((up['y1'] - up['y0']) / RL.ROW_RISE))
    len_lo = math.hypot(lo['d1'] - lo['d0'], lo['y1'] - lo['y0']) / rows_lo
    len_up = math.hypot(up['d1'] - up['d0'], up['y1'] - up['y0']) / rows_up

    s = Part('stands_lower', ['seats', 'concrete'])
    # pitch-side wall (hidden behind the advertising boards) + sloped seat deck
    d0 = lo['d0']
    prof = [(d0, 0.30), (d0, slope_y(lo, d0))]
    loft(s, ring0, ts, prof, ['i'], ['concrete'], uscale=5, vscale=5)
    loft(s, ring0, ts, [(d0, slope_y(lo, d0)), (lo['d1'] + 0.3, slope_y(lo, lo['d1'] + 0.3))], ['u'], ['seats'],
         uscale=SEAT_ROW_U, vscale=len_lo)
    if details:
        aisles(s, ring0, lo, 48, lambda t, d: slope_y(t, d), 'concrete', extra=0.3)
    finish(s, tex_dir)

    c = Part('concourse', ['concrete', 'steel_dark'])
    dl = lo['d1'] + 0.3
    yl = slope_y(lo, dl)
    yc = mid['y1'] - SINK
    prof = [(dl, yl), (dl, yc), (up['d0'], yc)]
    loft(c, ring0, ts, prof, ['i', 'u'], ['concrete', 'concrete'], uscale=6, vscale=6)
    if details:   # balustrade on the concourse edge (dark steel: front face + cap)
        loft(c, ring0, ts, [(dl, yc), (dl, yc + 1.0), (dl + 0.18, yc + 1.0)], ['i', 'u'], ['steel_dark'] * 2, uscale=6, vscale=6)
    finish(c, tex_dir)

    u = Part('stands_upper', ['seats', 'concrete'])
    loft(u, ring0, ts, [(up['d0'], slope_y(up, up['d0'])), (up['d1'], slope_y(up, up['d1']))], ['u'], ['seats'],
         uscale=SEAT_ROW_U, vscale=len_up)
    if details:
        aisles(u, ring0, up, 48, lambda t, d: slope_y(t, d), 'concrete')
    # back walkway and rear wall (down to the podium; hidden behind the glazing)
    yb = slope_y(up, up['d1'])
    loft(u, ring0, ts, [(up['d1'], yb), (RL.FACADE_D, yb)], ['u'], ['concrete'], uscale=6, vscale=6)
    # rear wall of the bowl up to the roof underside (closes the gap seen from inside when the facade is hidden)
    loft(u, ring0, ts, [(RL.FACADE_D, 0.8), (RL.FACADE_D, float(RL.roof_under_y(RL.FACADE_D)) + 0.02)], ['i'], ['concrete'],
         uscale=6, vscale=6)
    finish(u, tex_dir)

    # ---- podium: dark base ring around the facade ---------------------------------
    pod = Part('podium', ['podium_dark'])
    prof = [(43.0, 0.8), (49.4, 0.8), (49.4, 0.40), (52.0, 0.40), (52.0, 0.0)]
    loft(pod, ring0, ts, prof, ['u', 'o', 'u', 'o'], ['podium_dark'] * 4, uscale=6, vscale=6)
    finish(pod, tex_dir)


# =============================================================================
# STAGE 2 - roof
# =============================================================================
def stage2(tex_dir):
    ring = RL.Ring(RL.PANEL_D_REF)
    NP = RL.N_PANELS
    span = RL.ROOF_DOUT - RL.ROOF_DIN
    X, Z = RL.TEX_X, RL.TEX_Z

    def planar_uv(P):                    # P (..., 3) three coords -> (u, v_blender) top-down map
        u = (P[..., 0] + X) / (2 * X)
        v = 1.0 - (P[..., 2] + Z) / (2 * Z)
        return np.stack([u, v], -1)

    # ---- top: cushion surface with real pillow displacement ------------------------
    sub_t, sub_d = 6, 5
    nt = NP * sub_t
    ts = np.arange(nt) * ring.P / nt
    nd = RL.N_CUSHIONS * sub_d + 1
    dd = RL.ROOF_DIN + span * np.arange(nd) / (nd - 1)
    x, z, nx, nz = ring.point(ts[:, None], dd[None, :])
    pu = ((np.arange(nt) % sub_t) / sub_t)[:, None]
    jj = np.arange(nd)
    pv = np.where(jj % sub_d == 0, 0.0, (jj % sub_d) / sub_d)[None, :]
    h = RL.PILLOW_AMP * RL.pillow(pu, pv)
    y = RL.roof_top_y(dd)[None, :] + h
    P = np.stack([x, np.broadcast_to(y, x.shape), z], -1)
    Pw = np.concatenate([P, P[:1]], 0)
    UV = planar_uv(Pw)
    top = Part('roof_top', ['roof_fabric'])
    grid_surface(top, P, UV, 'roof_fabric', 'u', closed=True)
    finish(top, tex_dir)

    # ---- underside, outer rim, inner ring --------------------------------------------
    ts2 = np.arange(NP * 2) * ring.P / (NP * 2)
    under = Part('roof_under', ['roof_under', 'steel_dark'])
    nu = 10
    du = RL.ROOF_DIN + 0.5 + (span - 0.5) * np.arange(nu) / (nu - 1)
    x, z, nx, nz = ring.point(ts2[:, None], du[None, :])
    P = np.stack([x, np.broadcast_to(RL.roof_under_y(du)[None, :], x.shape), z], -1)
    UVu = np.zeros((len(ts2) + 1, nu, 2)) + 0.5
    grid_surface(under, P, UVu, 'roof_under', 'd', nxz=np.stack([nx[:, 0], nz[:, 0]], -1), closed=True)
    # outer rim: soft raised bead + thin outer face
    dO = RL.ROOF_DOUT
    yt, yu = float(RL.roof_top_y(dO)), float(RL.roof_under_y(dO))
    rim = [(dO, yt), (dO + 0.12, yt + 0.30), (dO + 0.40, yt + 0.38), (dO + 0.62, yt + 0.15), (dO + 0.70, yt - 0.40),
           (dO + 0.70, yu + 0.30), (dO + 0.55, yu - 0.05), (dO, yu)]
    ts3 = ring.samples(arc_seg=24, extra=np.arange(NP * 2) * ring.P / (NP * 2))
    loft(under, ring, ts3, rim, ['u', 'u', 'o', 'o', 'o', 'd', 'd'], ['roof_under'] * 7, uscale=6, vscale=6)
    # inner steel ring (dark fascia around the opening)
    dI = RL.ROOF_DIN
    ytI, yuI = float(RL.roof_top_y(dI)), float(RL.roof_under_y(dI))
    ring_prof = [(dI + 0.55, ytI + 0.28), (dI - 0.35, ytI + 0.28), (dI - 0.55, ytI + 0.05), (dI - 0.55, yuI - 0.60),
                 (dI + 0.55, yuI - 0.60)]
    loft(under, ring, ts3, ring_prof, ['u', 'u', 'i', 'd'], ['steel_dark'] * 4, uscale=6, vscale=6)
    # radial ribs on the underside (every panel seam) + two concentric beams
    ribs_t = np.arange(NP) * ring.P / NP
    drib = RL.ROOF_DIN + 0.9 + (span - 1.2) * np.arange(7) / 6
    xr, zr, nxr, nzr = ring.point(ribs_t[:, None], drib[None, :])
    tx, tz = -nzr, nxr                                      # tangential unit vectors
    yr = RL.roof_under_y(drib)[None, :] + np.zeros_like(xr)
    wr, hr = 0.16, 0.20
    corners = {
        'L0': (xr - tx * wr, yr - 0.0, zr - tz * wr), 'L1': (xr - tx * wr, yr - hr, zr - tz * wr),
        'R0': (xr + tx * wr, yr - 0.0, zr + tz * wr), 'R1': (xr + tx * wr, yr - hr, zr + tz * wr),
    }
    C = {k: np.stack(v, -1) for k, v in corners.items()}
    for (a, b, tag) in (('L0', 'L1', 'L'), ('L1', 'R1', 'B'), ('R1', 'R0', 'R')):
        S = np.stack([C[a], C[b]], 2)                        # (ribs, nd, 2, 3)
        nr, nd_, _, _ = S.shape
        Vv = S.reshape(-1, 3)
        I, J = np.meshgrid(np.arange(nr), np.arange(nd_ - 1), indexing='ij')
        ix = lambda i, j, s: (i * nd_ + j) * 2 + s  # noqa: E731
        Q = np.stack([ix(I, J, 0), ix(I, J + 1, 0), ix(I, J + 1, 1), ix(I, J, 1)], -1).reshape(-1, 4)
        N = _quad_normals(Vv[Q])
        # expected: B -> down; L -> tangent-backwards; R -> tangent-forwards
        if tag == 'B':
            bad = N[:, 1] > 0
        else:
            tt = np.repeat(np.stack([tx[:, 0], tz[:, 0]], -1), nd_ - 1, axis=0)
            dot = N[:, 0] * tt[:, 0] + N[:, 2] * tt[:, 1]
            bad = dot > 0 if tag == 'L' else dot < 0
        Q[bad] = Q[bad][:, ::-1]
        under.add_quads(Vv, Q, np.zeros((len(Q), 4, 2)) + 0.5, 'steel_dark')
    for sp in (1 / 3, 2 / 3):
        dc = RL.ROOF_DIN + span * sp
        yc = float(RL.roof_under_y(dc))
        prof = [(dc - 0.18, yc), (dc - 0.18, yc - 0.34), (dc + 0.18, yc - 0.34), (dc + 0.18, yc)]
        loft(under, ring, ts3, prof, ['i', 'd', 'o'], ['steel_dark'] * 3, uscale=6, vscale=6)
    finish(under, tex_dir)

    # ---- flood-light housings under the inner edge ------------------------------------
    lights = Part('roof_lights', ['steel_dark'])
    dl = RL.ROOF_DIN + 1.5
    rl = RL.Ring(dl)
    nl = int(round(rl.P / 2.4))
    tl = (np.arange(nl) + 0.5) * rl.P / nl
    xl, zl, nxl, nzl = rl.point(tl, dl)
    yl = float(RL.roof_under_y(dl)) - 0.55
    ctr = np.stack([xl, zl], -1)
    ax_u = np.stack([-nzl, nxl], -1)                         # tangential
    ax_v = np.stack([nxl, nzl], -1)                          # radial (outwards)
    box_prism(lights, ctr, ax_u, ax_v, 0.75, 0.40, yl - 0.32, yl + 0.32, 'steel_dark')
    finish(lights, tex_dir)


# =============================================================================
# STAGE 3 - facade colonnade + glazing + cornice, south entrance building
# =============================================================================
N_COL = 120
D_COL = 46.4
Y_BASE, Y_TOP = 0.8, 34.5


def stage3(tex_dir):
    rf = RL.Ring(D_COL)
    fac = Part('facade', ['facade_stone', 'facade_glass', 'podium_dark'])
    # columns (octagonal piers)
    tc = (np.arange(N_COL) + 0.5) * rf.P / N_COL
    x, z, nx, nz = rf.point(tc, D_COL)
    ctr = np.stack([x, z], -1)
    ax_u = np.stack([-nz, nx], -1)
    ax_v = np.stack([nx, nz], -1)
    box_prism(fac, ctr, ax_u, ax_v, 0.68, 0.70, Y_BASE, Y_TOP, 'facade_stone', caps=(False, False), chamfer=0.22)
    ts = rf.samples(arc_seg=24, extra=np.arange(N_COL) * rf.P / N_COL)
    # dark glazing behind the colonnade (bay-aligned texture: one tile per bay, one per ~9.6 m of height)
    bay = rf.P / N_COL
    d_gl = 46.05
    loft(fac, rf, ts, [(d_gl, 3.6), (d_gl, 32.5)], ['o'], ['facade_glass'],
         u_override=lambda t, d: np.concatenate([t / bay + 0.5, [rf.P / bay + 0.5]]), vscale=14.0)
    # dark base band (plinth), mid floor-plate band, cornice
    loft(fac, rf, ts, [(45.85, 4.2), (46.95, 4.2), (46.95, Y_BASE)], ['u', 'o'], ['podium_dark'] * 2, uscale=6, vscale=6)
    for y0, y1 in ((16.7, 18.1),):
        loft(fac, rf, ts, [(45.85, y1), (46.85, y1), (46.85, y0), (45.85, y0)], ['u', 'o', 'd'], ['facade_stone'] * 3,
             uscale=6, vscale=6)
    loft(fac, rf, ts, [(45.85, 34.5), (47.15, 34.5), (47.15, 32.3), (45.85, 32.3)], ['u', 'o', 'd'], ['facade_stone'] * 3,
         uscale=6, vscale=6)
    finish(fac, tex_dir)
    stage3_south(tex_dir)


def end_cap(part, ring, t, rects, direction, mat):
    """Flat quads closing an open loft at parameter t. rects = [(d0, d1, y0, y1)], direction = +1/-1 (outwards along t)."""
    for d0, d1, y0, y1 in rects:
        xa, za, _, _ = ring.point(np.array([t]), d0)
        xb, zb, _, _ = ring.point(np.array([t]), d1)
        V = np.array([[xa[0], y0, za[0]], [xb[0], y0, zb[0]], [xb[0], y1, zb[0]], [xa[0], y1, za[0]]])
        tg = np.array([-ring.point(np.array([t]), 0)[3][0], 0, ring.point(np.array([t]), 0)[2][0]]) * direction
        n = np.cross(V[1] - V[0], V[3] - V[0])
        Q = [[0, 1, 2, 3]] if np.dot(n, tg) > 0 else [[0, 3, 2, 1]]
        part.add_quads(V, Q, np.zeros((1, 4, 2)) + 0.5, mat)


def arches(part, ring, t_centres, d, y0, y_spring, w, mat, off=0.06):
    r = w / 2
    th = np.linspace(0, math.pi, 9)
    for t in t_centres:
        x, z, nx, nz = (a[0] for a in ring.point(np.array([t]), d + off))
        tx, tz = -nz, nx
        prof = [(-r, y0), (r, y0)] + [(r * math.cos(a), y_spring + r * math.sin(a)) for a in th]
        pts = np.array([[x + a_ * tx, y_, z + a_ * tz] for a_, y_ in prof])
        poly_fan(part, pts, [x, (y0 + y_spring) / 2, z], [nx, 0, nz], mat)


def stage3_south(tex_dir):
    sb = Part('south_building', ['facade_stone', 'brick_red', 'concrete', 'facade_glass'])
    rs = RL.Ring(58.0)
    t0 = rs.P / 4                       # south centre
    half = 48.0
    ts = ts_range(rs, t0 - half, t0 + half)
    # stepped, curved body: three terraces rising towards the stadium
    prof = [(67.0, 0.0), (67.0, 3.9), (60.0, 3.9), (60.0, 6.8), (54.0, 6.8), (54.0, 9.4), (47.0, 9.4)]
    loft(sb, rs, ts, prof, ['o', 'u', 'o', 'u', 'o', 'u'], ['facade_stone', 'concrete', 'facade_stone', 'concrete', 'facade_stone', 'concrete'],
         uscale=6, vscale=6, closed=False)
    rects = [(47.0, 67.0, 0.0, 3.9), (47.0, 60.0, 3.9, 6.8), (47.0, 54.0, 6.8, 9.4)]
    end_cap(sb, rs, t0 - half, rects, -1, 'facade_stone')
    end_cap(sb, rs, t0 + half, rects, +1, 'facade_stone')
    # central portal
    hp = 17.0
    tp = ts_range(rs, t0 - hp, t0 + hp)
    loft(sb, rs, tp, [(62.0, 3.9), (62.0, 11.4), (54.0, 11.4)], ['o', 'u'], ['facade_stone', 'concrete'], uscale=6, vscale=6, closed=False)
    loft(sb, rs, ts_range(rs, t0 - hp + 3, t0 + hp - 3), [(62.06, 5.4), (62.06, 10.0)], ['o'], ['facade_glass'],
         uscale=4.3, vscale=9.6, closed=False)
    prect = [(54.0, 62.0, 3.9, 11.4)]
    end_cap(sb, rs, t0 - hp, prect, -1, 'facade_stone')
    end_cap(sb, rs, t0 + hp, prect, +1, 'facade_stone')
    # arcade on the outer wall (dark arched openings)
    ta = t0 + (np.arange(-9, 10)) * 5.0
    arches(sb, rs, ta, 67.0, 0.3, 2.1, 3.2, 'facade_glass')
    ta2 = t0 + (np.arange(-7, 8)) * 5.0
    arches(sb, rs, ta2, 60.0, 4.2, 5.1, 2.6, 'facade_glass')
    # reddish-brown end pavilions with hipped roofs
    for sgn in (-1, 1):
        tt = t0 + sgn * 44.0
        x, z, nx, nz = rs.point(np.array([tt]), 59.0)
        ctr = np.array([[x[0], z[0]]])
        au = np.array([[-nz[0], nx[0]]])
        av = np.array([[nx[0], nz[0]]])
        hu, hv, hh = 4.8, 6.2, 11.5
        box_prism(sb, ctr, au, av, hu, hv, 0.0, hh, 'brick_red', caps=(False, False))
        ex, ez = hu + 0.6, hv + 0.6
        base = [(-ex, -ez), (ex, -ez), (ex, ez), (-ex, ez)]
        P3 = np.array([[x[0] + a_ * au[0, 0] + b_ * av[0, 0], hh - 0.4, z[0] + a_ * au[0, 1] + b_ * av[0, 1]] for a_, b_ in base])
        apex = np.array([x[0], hh + 3.0, z[0]])
        V = np.vstack([P3, apex])
        tris = []
        for i in range(4):
            tri = np.array([i, (i + 1) % 4, 4])
            nrm = np.cross(V[tri[1]] - V[tri[0]], V[tri[2]] - V[tri[0]])
            if np.dot(nrm, V[tri].mean(0) - np.array([x[0], hh, z[0]])) < 0:
                tri = tri[::-1]
            tris.append(tri)
        sb.add_prims(V, [], [], np.array(tris), np.zeros((4, 3, 2)) + 0.5, 'brick_red')
        # eave underside is hidden; dark arched windows on the front + back faces
        for fv, off in ((1, hv), (-1, -hv)):
            for k_ in (-1, 0, 1):
                xx, zz = x[0] + k_ * 2.6 * au[0, 0] + off * av[0, 0] + fv * 0.06 * av[0, 0], z[0] + k_ * 2.6 * au[0, 1] + off * av[0, 1] + fv * 0.06 * av[0, 1]
                th = np.linspace(0, math.pi, 9)
                rr = 1.1
                prof = [(-rr, 4.0), (rr, 4.0)] + [(rr * math.cos(a_), 6.6 + rr * math.sin(a_)) for a_ in th]
                pts = np.array([[xx + a_ * au[0, 0], y_, zz + a_ * au[0, 1]] for a_, y_ in prof])
                poly_fan(sb, pts, [xx, 5.3, zz], [fv * av[0, 0], 0, fv * av[0, 1]], 'facade_glass')
    finish(sb, tex_dir)


