# =============================================================================
# QA report (loose geometry, degenerate faces, UV range, vertex counts)
# =============================================================================
def qa_report():
    import bmesh
    print('QA:')
    for name, o in OBJECTS.items():
        bm = bmesh.new()
        bm.from_mesh(o.data)
        loose = sum(1 for v in bm.verts if not v.link_faces)
        degenerate = sum(1 for f in bm.faces if f.calc_area() < 1e-9)
        uv = bm.loops.layers.uv.active
        uvs = np.array([l[uv].uv[:] for f in bm.faces for l in f.loops]) if uv else np.zeros((1, 2))
        print('  %-16s verts %6d  faces %6d  loose %d  degenerate %d  uv [%.2f..%.2f, %.2f..%.2f]  loc %s rot %s scale %s' % (
            name, len(bm.verts), len(bm.faces), loose, degenerate, uvs[:, 0].min(), uvs[:, 0].max(), uvs[:, 1].min(), uvs[:, 1].max(),
            tuple(round(c, 3) for c in o.location), tuple(round(c, 3) for c in o.rotation_euler), tuple(round(c, 3) for c in o.scale)))
        bm.free()


