def export_glb(path):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    bpy.ops.object.select_all(action='DESELECT')
    for o in OBJECTS.values():
        o.select_set(True)
    bpy.context.view_layer.objects.active = next(iter(OBJECTS.values()))
    bpy.ops.export_scene.gltf(
        filepath=path, export_format='GLB', export_yup=True, export_apply=True,
        use_selection=True, export_image_format='JPEG', export_jpeg_quality=88,
        export_materials='EXPORT', export_cameras=False, export_lights=False,
        export_texcoords=True, export_normals=True, export_tangents=False, export_vertex_color='NONE',
        export_animations=False, export_extras=False, export_draco_mesh_compression_enable=False)
    print('exported %s  %.2f MB' % (path, os.path.getsize(path) / 1e6))


