def setup_preview_scene(samples):
    sc = bpy.context.scene
    sc.render.engine = 'CYCLES'
    sc.cycles.device = 'CPU'
    sc.cycles.samples = samples
    sc.cycles.use_denoising = False
    sc.cycles.max_bounces = 4
    sc.cycles.diffuse_bounces = 2
    sc.cycles.glossy_bounces = 2
    sc.render.resolution_percentage = 100
    sc.render.image_settings.file_format = 'PNG'
    sc.view_settings.view_transform = 'Standard'
    sc.view_settings.look = 'None'
    sc.view_settings.exposure = -0.2
    w = bpy.data.worlds.new('sky')
    sc.world = w
    w.use_nodes = True
    bg = w.node_tree.nodes['Background']
    bg.inputs['Color'].default_value = (0.42, 0.55, 0.78, 1.0)
    bg.inputs['Strength'].default_value = 1.0
    sun = bpy.data.lights.new('sun', 'SUN')
    sun.energy = 3.2
    sun.angle = math.radians(2.5)
    so = bpy.data.objects.new('preview_sun', sun)
    bpy.context.scene.collection.objects.link(so)
    # sun from south-west, ~42 degrees up (three coords dir -> blender)
    d = Vector((0.55, 0.78, 0.45)).normalized()
    so.rotation_euler = Vector((d.x, -d.z, d.y)).to_track_quat('Z', 'Y').to_euler()
    so.hide_render = False
    # ground
    bpy.ops.mesh.primitive_plane_add(size=1400, location=(0, 0, -0.05))
    g = bpy.context.active_object
    g.name = 'preview_ground'
    gm = bpy.data.materials.new('preview_ground')
    gm.use_nodes = True
    gm.node_tree.nodes['Principled BSDF'].inputs['Base Color'].default_value = (0.11, 0.115, 0.12, 1)
    gm.node_tree.nodes['Principled BSDF'].inputs['Roughness'].default_value = 0.95
    g.data.materials.append(gm)


def render_view(name, outdir, prefix=''):
    v = PREVIEW_VIEWS[name]
    sc = bpy.context.scene
    sc.render.resolution_x, sc.render.resolution_y = v['res']
    bpy.data.worlds['sky'].node_tree.nodes['Background'].inputs['Strength'].default_value = 3.2 if v.get('fill') else 1.0
    sc.cycles.diffuse_bounces = 4 if v.get('fill') else 2
    cam_d = bpy.data.cameras.new('cam')
    if 'ortho' in v:
        cam_d.type = 'ORTHO'
        cam_d.ortho_scale = v['ortho']
    else:
        cam_d.lens = v['lens']
        cam_d.sensor_width = 36
    cam_d.clip_start, cam_d.clip_end = 0.5, 3000
    co = bpy.data.objects.new('cam', cam_d)
    sc.collection.objects.link(co)
    pos = to_bl(np.array(v['pos'], float))
    tgt = to_bl(np.array(v['tgt'], float))
    co.location = Vector(pos)
    co.rotation_euler = (Vector(tgt) - Vector(pos)).to_track_quat('-Z', 'Y').to_euler()
    sc.camera = co
    os.makedirs(outdir, exist_ok=True)
    path = os.path.join(outdir, '%s%s.png' % (prefix, name))
    sc.render.filepath = path
    t0 = time.time()
    bpy.ops.render.render(write_still=True)
    print('  preview %s %.1fs' % (path, time.time() - t0))
    bpy.data.objects.remove(co)


