def main():
    a = parse_args()
    t0 = time.time()
    tex_dir = a.tex
    if not os.path.exists(os.path.join(tex_dir, 'roof_top.jpg')):
        print('textures missing -> running make_textures.py')
        subprocess.check_call(['python3', os.path.join(HERE, 'make_textures.py'), '--out', tex_dir])
    reset_scene()
    stages = [stage1, stage2, stage3, stage4]
    for i, fn in enumerate(stages[:a.stage], 1):
        print('stage', i)
        if fn is stage1:
            fn(tex_dir, details=a.stage >= 4)
        else:
            fn(tex_dir)
    total = sum(len(o.data.loops) - 2 * len(o.data.polygons) for o in OBJECTS.values())   # triangles after triangulation
    print('objects:', ', '.join(OBJECTS), ' | triangles: %d' % total)
    qa_report()
    if not a.no_export:
        export_glb(a.out)
    if a.previews:
        setup_preview_scene(a.samples)
        for name in a.previews.split(','):
            render_view(name.strip(), a.preview_dir, a.preview_prefix)
    if a.save_blend:
        bpy.ops.wm.save_as_mainfile(filepath=a.save_blend)
    print('done in %.1fs' % (time.time() - t0))


if __name__ == '__main__':
    main()
